            #region Combine
            public ErrorMask Combine(ErrorMask? rhs)
            {
                if (rhs == null) return this;
                var ret = new ErrorMask();
                ret.EDID = this.EDID.Combine(rhs.EDID);
                ret.Keywords = new MaskItem<Exception?, IEnumerable<(int Index, Exception Value)>?>(Noggog.ExceptionExt.Combine(this.Keywords?.Overall, rhs.Keywords?.Overall), Noggog.ExceptionExt.Combine(this.Keywords?.Specific, rhs.Keywords?.Specific));
                ret.LNAM = this.LNAM.Combine(rhs.LNAM);
                ret.MNAM = this.MNAM.Combine(rhs.MNAM);
                ret.SPGD = this.SPGD.Combine(rhs.SPGD);
                ret.NNAM = this.NNAM.Combine(rhs.NNAM);
                ret.RFCT = this.RFCT.Combine(rhs.RFCT);
                ret.PNAM = this.PNAM.Combine(rhs.PNAM);
                ret.JNAM = this.JNAM.Combine(rhs.JNAM);
                ret.NAM4 = this.NAM4.Combine(rhs.NAM4);
                ret.NAM1 = this.NAM1.Combine(rhs.NAM1);
                ret.SkyStatics = new MaskItem<Exception?, IEnumerable<(int Index, Exception Value)>?>(Noggog.ExceptionExt.Combine(this.SkyStatics?.Overall, rhs.SkyStatics?.Overall), Noggog.ExceptionExt.Combine(this.SkyStatics?.Specific, rhs.SkyStatics?.Specific));
                ret.DALC = this.DALC.Combine(rhs.DALC);
                ret.Model = this.Model.Combine(rhs.Model, (l, r) => l.Combine(r));
                ret.GodRays = this.GodRays.Combine(rhs.GodRays);
                ret.VNAM = this.VNAM.Combine(rhs.VNAM);
                ret.WNAM = this.WNAM.Combine(rhs.WNAM);
                ret.XNAM = this.XNAM.Combine(rhs.XNAM);
                ret.ZNAM = this.ZNAM.Combine(rhs.ZNAM);
                ret.YNAM = this.YNAM.Combine(rhs.YNAM);
                ret.KNAM = this.KNAM.Combine(rhs.KNAM);
                ret.INAM = this.INAM.Combine(rhs.INAM);
                ret.DATA = this.DATA.Combine(rhs.DATA);
                ret.TNAM = this.TNAM.Combine(rhs.TNAM);
                ret.TX_00TX = this.TX_00TX.Combine(rhs.TX_00TX);
                ret.TX_10TX = this.TX_10TX.Combine(rhs.TX_10TX);
                ret.TX_20TX = this.TX_20TX.Combine(rhs.TX_20TX);
                ret.TX_30TX = this.TX_30TX.Combine(rhs.TX_30TX);
                ret.TX_40TX = this.TX_40TX.Combine(rhs.TX_40TX);
                ret.TX_50TX = this.TX_50TX.Combine(rhs.TX_50TX);
                ret.TX_60TX = this.TX_60TX.Combine(rhs.TX_60TX);
                ret.TX_70TX = this.TX_70TX.Combine(rhs.TX_70TX);
                ret.TX_80TX = this.TX_80TX.Combine(rhs.TX_80TX);
                ret.TX_90TX = this.TX_90TX.Combine(rhs.TX_90TX);
                ret.A0TX = this.A0TX.Combine(rhs.A0TX);
                ret.E0TX = this.E0TX.Combine(rhs.E0TX);
                ret.F0TX = this.F0TX.Combine(rhs.F0TX);
                ret.FNAM = this.FNAM.Combine(rhs.FNAM);
                ret.HNAM = this.HNAM.Combine(rhs.HNAM);
                ret.IMSP = this.IMSP.Combine(rhs.IMSP);
                ret.K0TX = this.K0TX.Combine(rhs.K0TX);
                ret.L0TX = this.L0TX.Combine(rhs.L0TX);
                ret.NAM0 = this.NAM0.Combine(rhs.NAM0);
                ret.QNAM = this.QNAM.Combine(rhs.QNAM);
                ret.RNAM = this.RNAM.Combine(rhs.RNAM);
                ret.Sounds = this.Sounds.Combine(rhs.Sounds, (l, r) => l.Combine(r));
                ret.UNAM = this.UNAM.Combine(rhs.UNAM);
                return ret;
            }
            public static ErrorMask? Combine(ErrorMask? lhs, ErrorMask? rhs)
            {
                if (lhs != null && rhs != null) return lhs.Combine(rhs);
                return lhs ?? rhs;
            }
