        #region Mutagen
        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(IWeatherGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (obj.Keywords is {} KeywordsItem)
            {
                foreach (var item in KeywordsItem)
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (FormLinkInformation.TryFactory(obj.MNAM, out var MNAMInfo))
            {
                yield return MNAMInfo;
            }
            foreach (var item in obj.SkyStatics)
            {
                yield return FormLinkInformation.Factory(item);
            }
            if (obj.Model is {} ModelItems)
            {
                foreach (var item in ModelItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (FormLinkInformation.TryFactory(obj.GodRays, out var GodRaysInfo))
            {
                yield return GodRaysInfo;
            }
            if (FormLinkInformation.TryFactory(obj.TNAM, out var TNAMInfo))
            {
                yield return TNAMInfo;
            }
            if (obj.Sounds is {} SoundsItems)
            {
                foreach (var item in SoundsItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            yield break;
        }
        
        #region Duplicate
        public Weather Duplicate(
            IWeatherGetter item,
            FormKey formKey,
            TranslationCrystal? copyMask)
        {
            var newRec = new Weather(formKey, item.FormVersion);
            newRec.DeepCopyIn(item, default(ErrorMaskBuilder?), copyMask);
            return newRec;
        }
        
